async function rollupWorkspace(
  pool: Pool,
  workspaceId: string,
  day: string,
  preserveFullerSnapshot: boolean,
): Promise<number> {
  const client = await pool.connect();
  try {
    await client.query("BEGIN");
    await setCurrentWorkspaceRoutingEpoch(client, workspaceId);
    await client.query("SELECT pg_advisory_xact_lock(hashtextextended($1, 0))", [
      `skillplane-rollup:${workspaceId}:${day}`,
    ]);
    const source = await client.query<{
      event_count: string;
      latest_event_at: Date | null;
    }>(
      `SELECT count(*)::text AS event_count, max(occurred_at) AS latest_event_at
         FROM audit_events
        WHERE workspace_id = $1
          AND occurred_at >= ($2::date::timestamp AT TIME ZONE 'UTC')
          AND occurred_at < (($2::date + 1)::timestamp AT TIME ZONE 'UTC')`,
      [workspaceId, day],
    );
    const row = source.rows[0];
    const eventCount = Number(row?.event_count ?? 0);
    if (preserveFullerSnapshot) {
      const existing = await client.query<{ source_event_count: string }>(
        `SELECT source_event_count
           FROM analytics_rollup_runs
          WHERE workspace_id = $1 AND day = $2::date`,
        [workspaceId, day],
      );
      const preservedEventCount = Number(existing.rows[0]?.source_event_count ?? 0);
      if (existing.rows[0] && preservedEventCount >= eventCount) {
        await client.query("COMMIT");
        return preservedEventCount;
      }
    }
    await client.query(
      "DELETE FROM analytics_daily_dimensions WHERE workspace_id = $1 AND day = $2",
      [workspaceId, day],
    );
    await client.query(
      "DELETE FROM analytics_daily_summary WHERE workspace_id = $1 AND day = $2",
      [workspaceId, day],
    );
    await insertSummary(client, workspaceId, day);
    await insertDimensions(client, workspaceId, day);
    await client.query(
      `INSERT INTO analytics_rollup_runs (
         workspace_id, day, source_event_count, source_latest_event_at,
         completed_at
       ) VALUES ($1, $2, $3, $4, now())
       ON CONFLICT (workspace_id, day)
       DO UPDATE SET
         source_event_count = EXCLUDED.source_event_count,
         source_latest_event_at = EXCLUDED.source_latest_event_at,
         completed_at = now()`,
      [workspaceId, day, eventCount, row?.latest_event_at ?? null],
    );
    await client.query("COMMIT");
    return eventCount;
  } catch (error) {
    await client.query("ROLLBACK").catch(() => undefined);
    throw error;
  } finally {
    client.release();
  }
}

export async function rollupUtcDay(
  pool: Pool,
  options: {
    readonly day: string;
    readonly workspaceId?: string;
    readonly preserveFullerSnapshot?: boolean;
  },
): Promise<RollupResult> {
  const day = requireDay(options.day);
  const workspaces = options.workspaceId
    ? [{ workspace_id: options.workspaceId }]
    : (
        await pool.query<{ workspace_id: string }>(
          `SELECT workspace_id
             FROM (
               SELECT DISTINCT workspace_id
                 FROM audit_events
                WHERE occurred_at >= ($1::date::timestamp AT TIME ZONE 'UTC')
                  AND occurred_at < (($1::date + 1)::timestamp AT TIME ZONE 'UTC')
               UNION
               SELECT workspace_id
                 FROM analytics_rollup_runs
                WHERE day = $1::date
             ) source
            ORDER BY workspace_id`,
          [day],
        )
      ).rows;
  let sourceEvents = 0;
  let processedWorkspaces = 0;
  for (const row of workspaces) {
    try {
      sourceEvents += await rollupWorkspace(
        pool,
        row.workspace_id,
        day,
        options.preserveFullerSnapshot ?? false,
      );
      processedWorkspaces += 1;
    } catch (error) {
      if (!(error instanceof WorkspaceMaintenanceFencedError)) throw error;
    }
  }
  return { day, workspaces: processedWorkspaces, sourceEvents };
}

