import { execFileSync } from 'node:child_process';
import assert from 'node:assert/strict';
const root = process.cwd();
const { Pool } = createRequire(`${root}/package.json`)('pg');
const observer = new Pool({ connectionString: 'postgresql://ski19_round@127.0.0.1:65445/postgres' });
const AsyncFunction = Object.getPrototypeOf(async function () {}).constructor;
try {
  for (const file of ['utc-rollups.integration.test.ts', 'migrated-workspace-maintenance.integration.test.ts']) {
    const path = `packages/api/tests/integration/${file}`;
    for (const version of ['old', 'new']) {
      const source = version === 'old' ? execFileSync('git', ['show', `5cc42dd:${path}`], { encoding: 'utf8' }) : readFileSync(`${root}/${path}`, 'utf8');
      const start = source.indexOf('const admin = new Pool');
      const bodyStart = source.indexOf('await migrateDatabase(', start);
      const finallyStart = source.indexOf('} finally {', bodyStart);
      const finalEnd = source.lastIndexOf('\n}', source.length); // UTC callback has a differently indented ending.
      const cleanupEnd = file.startsWith('utc') ? source.lastIndexOf('\n  },') : source.lastIndexOf('\n},');
      const setupAndCleanup = (source.slice(start, bodyStart) + 'await probe(address, database);\n' + source.slice(finallyStart, cleanupEnd))
        .replace('let database: Pool | undefined;', 'let database;');
      for (const scenario of ['create-failure', 'drop-failure', 'body-failure', 'success']) {
        const name = `pr45_probe_${crypto.randomUUID().replaceAll('-', '').slice(0, 12)}_test`;
        const label = `pr45-${version}-${scenario}-${file.slice(0, 3)}`;
        const user = scenario === 'create-failure' ? 'ski19_no_create' : 'ski19_creator';
        const address = new URL(`postgresql://${user}@127.0.0.1:65445/postgres`);
        const pools = [];
        class ProbePool extends Pool {
          constructor(options) { super({ ...options, application_name: label }); pools.push(this); }
        }
        let error;
        try {
          await new AsyncFunction('Pool', 'address', 'name', 'timezone', 'day', 'probe', setupAndCleanup)(ProbePool, address, name, 'Asia/Kolkata', '2026-03-08', async (_address, database) => {
            await database.query('SELECT 1');
            if (scenario === 'drop-failure') await observer.query(`ALTER DATABASE "${name}" OWNER TO ski19_round`);
            if (scenario === 'body-failure') throw new Error('injected assertion failure');
          });
        } catch (caught) { error = caught; }
        try {
          if (scenario === 'success') assert.equal(error, undefined);
          else assert.ok(error, scenario);
          const { rows } = await observer.query('SELECT pid FROM pg_stat_activity WHERE application_name = $1', [label]);
          const expected = version === 'old' && ['create-failure', 'drop-failure'].includes(scenario) ? 1 : 0;
          assert.equal(rows.length, expected, `${file} ${version} ${scenario}: connections`);
          const databases = await observer.query('SELECT datname FROM pg_database WHERE datname = $1', [name]);
          assert.equal(databases.rowCount, scenario === 'drop-failure' ? 1 : 0);
          console.log(JSON.stringify({ file, version, scenario, errorCode: error?.code ?? error?.message, liveConnections: rows.length, remainingDatabases: databases.rowCount }));
        } finally {
          for (const pool of pools) if (!pool.ended) await pool.end();
          await observer.query(`DROP DATABASE IF EXISTS "${name}" WITH (FORCE)`);
        }
      }
    }
  }
} finally { await observer.end(); }
